    /**
     * The player's octave and offset of [pitch] (clamped to 0..[PITCH_MAX]) on the SAM Coupe's ([cms] false) or
     * the CMS's clock, as O shl 8 or N: the chip's lowest tone (O 0 N 0) below its range, its highest (O 7
     * N 255) above.
     */
    fun octaveOffset(pitch: Int, cms: Boolean): Int {
        val p = pitch.coerceIn(0, PITCH_MAX)
        val k = p / PITCH_UNITS_PER_OCTAVE
        val t = (if (cms) DIV_CMS else DIV_SAM)[p % PITCH_UNITS_PER_OCTAVE]
        var s = 0
        var d: Int
        if (t >= 131072) {
            s = -1
            d = (t + 256) shr 9
        } else {
            d = (t + 128) shr 8
            if (d >= 512) {
                s = -1
                d = (t + 256) shr 9
            }
        }
        val o = k + s
        return when {
            o < 0 -> 0
            o > 7 -> (7 shl 8) or 255
            else -> (o shl 8) or (511 - d)
        }
    }

    /** The chip's tone frequency for [octaveOffset] (O shl 8 or N): clock 2^O / (512 (511 - N)) Hz. */
    fun hz(octaveOffset: Int, cms: Boolean): Double {
        val o = octaveOffset shr 8
        val n = octaveOffset and 0xFF
        return (if (cms) CLOCK_CMS else CLOCK_SAM).toDouble() * (1 shl o) / (512.0 * (511 - n))
    }

